    <select id="subject">
        <option value="math">Math</option>
        <option value="science">Science</option>
        <option value="history">History</option>
    </select>
    <button onclick="loadData()">Load Data</button>
    <br><br>
    <input type="number" id="filterInput" placeholder="Filter by score">
    <button onclick="applyFilter()">Apply Filter</button>
    <br><br>
    <table id="gradesTable">
        <thead>
            <tr>
                <th onclick="sortTable('name')">Name</th>
                <th onclick="sortTable('score')">Score</th>
            </tr>
        </thead>
        <tbody>
            <!-- Table data will be populated here -->
        </tbody>
    </table>

    <script>
        function sortTable(column) {
            const table = document.getElementById("gradesTable");
            const tbody = table.querySelector("tbody");
            const rows = Array.from(tbody.rows);

            rows.sort((a, b) => {
                const aValue = a.cells[column === 'name' ? 0 : 1].textContent;
                const bValue = b.cells[column === 'name' ? 0 : 1].textContent;

                if (column === 'name') {
                    return aValue.localeCompare(bValue);
                } else {
                    return parseFloat(aValue) - parseFloat(bValue);
                }
            });

            // Clear the table body and append sorted rows
            tbody.innerHTML = '';
            rows.forEach(row => tbody.appendChild(row));
        }

        function applyFilter() {
            const filterValue = parseFloat(document.getElementById("filterInput").value);
            const table = document.getElementById("gradesTable");
            const tbody = table.querySelector("tbody");
            const rows = Array.from(tbody.rows);

            if (!isNaN(filterValue)) {
                rows.forEach(row => {
                    const score = parseFloat(row.cells[1].textContent);
                    row.style.display = score > filterValue ? '' : 'none';
                });
            } else {
                rows.forEach(row => {
                    row.style.display = '';
                });
            }
        }

        function loadData() {
            const subject = document.getElementById("subject").value;
            const xhr = new XMLHttpRequest();
            xhr.open("GET", `get_grades.php?subject=${subject}`, true);
            xhr.onload = function () {
                if (xhr.status === 200) {
                    const data = JSON.parse(xhr.responseText);
                    const tbody = document.querySelector("#gradesTable tbody");
                    tbody.innerHTML = '';
                    data.forEach(item => {
                        const row = document.createElement("tr");
                        row.innerHTML = `<td>${item.name}</td><td>${item.score}</td>`;
                        tbody.appendChild(row);
                    });
                }
            };
            xhr.send();
        }
    </script>
</body>
</html>
