  <a href="https://example.com" class="gradient-link">Click Me</a>

  <script>
    // Function to check if the user is on a mobile device with screen width less than 600px
    function isMobileDevice() {
      return window.innerWidth < 600;
    }

    // Function to change the background color of the heading every 2 seconds
    function changeHeadingColor() {
      const colors = ['#ff0000', '#00ff00', '#0000ff', '#ffff00', '#00ffff', '#ff00ff'];
      const heading = document.querySelector('.dynamic-heading');
      let index = 0;

      setInterval(() => {
        heading.style.backgroundColor = colors[index];
        index = (index + 1) % colors.length;
      }, 2000);
    }

    // Function to handle the link click based on device type
    function handleLinkClick(event) {
